(function(){
  var C={"segments": [{"label": "โดยตรง (8)", "value": 8, "color": "#e5484d", "display": "8", "label_en": ""}, {"label": "คู่ค้า/ทีม (~26)", "value": 26, "color": "#f5a524", "display": "~26", "label_en": ""}, {"label": "สแปม (1)", "value": 1, "color": "#8b5cf6", "display": "1", "label_en": ""}, {"label": "อัตโนมัติ/ส่งออก (~36)", "value": 36, "color": "#2f9e6b", "display": "~36", "label_en": ""}], "cv": "70", "cl": "เธรด", "cle": ""};
  var segs=C.segments;
  if(segs.length){
    var total=segs.reduce(function(a,d){return a+d.value},0),r=70,L=2*Math.PI*r,off=0,svg='';
    segs.forEach(function(d){var len=d.value/total*L;
      svg+='<circle cx="100" cy="100" r="'+r+'" fill="none" stroke="'+d.color+'" stroke-width="32" stroke-dasharray="'+len+' '+(L-len)+'" stroke-dashoffset="'+(-off)+'" transform="rotate(-90 100 100)"/>';off+=len;});
    svg+='<text x="100" y="102" text-anchor="middle" font-size="24" font-weight="700">'+C.cv+'</text><text class="sub th" x="100" y="124" text-anchor="middle" font-size="12">'+C.cl+'</text><text class="sub en" x="100" y="124" text-anchor="middle" font-size="12">'+(C.cle||C.cl)+'</text>';
    document.getElementById('donut').innerHTML=svg;
    document.getElementById('legend').innerHTML=segs.map(function(d){return '<div><span class="dot" style="background:'+d.color+'"></span>'+'<span class="th">'+d.label+'</span><span class="en">'+(d.label_en||d.label)+'</span>: <b>'+(d.display||d.value)+'</b></div>'}).join('');
  }
  var btns=root.querySelectorAll('.filters button'),groups=root.querySelectorAll('.group');
  btns.forEach(function(b){b.addEventListener('click',function(){
    btns.forEach(function(x){x.classList.remove('active')});b.classList.add('active');
    var f=b.dataset.f;groups.forEach(function(g){g.style.display=(f==='all'||g.dataset.g===f)?'':'none'});
  })});
})();


(function(){
  var R={"endpoint": "https://email-dashboard-refresh.hungryhub-acc.workers.dev", "updatedAt": "2026-10-22T08:20:00+07:00", "metaKey": "updated_at"};
  var btn=document.getElementById('refreshBtnD'),msg=document.getElementById('refreshMsgD');
  if(!btn)return;
  var KEY='dash_refresh_until',SKEY='dash_refresh_start',COOL=60*1000,MAXWAIT=8*60*1000,timer=null,poll=null,busy=false,last=null;
  function tx(a,b){return document.documentElement.getAttribute('data-lang')==='en'?b:a}
  function say(th,en,err){last=[th,en,err];msg.textContent=tx(th,en);msg.className=err?'err':'';}
  document.addEventListener('langchange',function(){if(last)msg.textContent=tx(last[0],last[1]);tick();});
  function fmt(ms){var s=Math.ceil(ms/1000),m=Math.floor(s/60);s=s%60;return m+':'+(s<10?'0':'')+s;}
  function fmtUp(ms){var s=Math.floor(ms/1000),m=Math.floor(s/60);s=s%60;return m+':'+(s<10?'0':'')+s;}
  function getN(k){try{return parseInt(localStorage.getItem(k)||'0',10)||0}catch(x){return 0}}
  function setN(k,v){try{if(v)localStorage.setItem(k,String(v));else localStorage.removeItem(k)}catch(x){}}
  function stage(el){
    if(el<8000)return ['ส่งคำสั่งแล้ว กำลังเริ่มงาน...','Request sent, starting...'];
    if(el<45000)return ['กำลังดึงอีเมลล่าสุด...','Fetching the latest emails...'];
    if(el<150000)return ['กำลังวิเคราะห์และสรุปอีเมล...','Analyzing and summarizing emails...'];
    return ['ใกล้เสร็จแล้ว (ปกติใช้ 3–5 นาที) หน้าจะรีโหลดเอง','Almost done (usually 3–5 min); the page will reload by itself'];
  }
  function stopTimers(){if(timer){clearInterval(timer);timer=null;}if(poll){clearInterval(poll);poll=null;}}
  function tick(){
    var st=getN(SKEY);
    if(busy&&st){
      var el=Date.now()-st;
      if(el>MAXWAIT){busy=false;setN(SKEY,0);stopTimers();say('ใช้เวลานานกว่าปกติ ลองรีเฟรชหน้านี้อีกครั้งในอีกสักครู่','Taking longer than usual; try refreshing this page again shortly',true);tick();return;}
      btn.disabled=true;btn.textContent=tx('กำลังอัปเดต... ','Updating... ')+fmtUp(el);var sg=stage(el);say(sg[0],sg[1]);return;
    }
    var left=getN(KEY)-Date.now();
    if(left>0){btn.disabled=true;btn.textContent=tx('อัปเดตตอนนี้ (รอ ','Update now (wait ')+fmt(left)+')';}
    else{btn.disabled=false;btn.textContent=tx('อัปเดตตอนนี้','Update now');if(!busy&&timer){clearInterval(timer);timer=null;}}
  }
  function startTimer(){if(!timer)timer=setInterval(tick,1000);tick();}
  function check(){
    fetch('meta.json?v='+Date.now(),{cache:'no-store'}).then(function(r){return r.json()}).then(function(m){
      if(m&&m[R.metaKey]&&m[R.metaKey]!==R.updatedAt){setN(SKEY,0);busy=false;stopTimers();btn.disabled=true;say('อัปเดตเสร็จแล้ว กำลังโหลดหน้าใหม่...','Update complete, reloading the page...');setTimeout(function(){location.reload()},500);}
    }).catch(function(){});
  }
  function startPolling(){if(poll)clearInterval(poll);poll=setInterval(check,10000);}
  function cooldownOnly(){busy=false;setN(SKEY,0);startTimer();}
  btn.addEventListener('click',function(){
    if(busy||getN(KEY)>Date.now())return;
    if(!R.endpoint){say('ยังไม่ได้ตั้งค่าการเชื่อมต่อการอัปเดต','Update connection is not configured',true);return;}
    busy=true;setN(SKEY,Date.now());setN(KEY,Date.now()+COOL);
    btn.disabled=true;btn.textContent=tx('กำลังอัปเดต... ','Updating... ')+'0:00';say('ส่งคำสั่งแล้ว กำลังเริ่มงาน...','Request sent, starting...');
    startTimer();startPolling();
    function fail(th,en,clear){busy=false;setN(SKEY,0);if(clear)setN(KEY,0);stopTimers();say(th,en,true);tick();}
    fetch(R.endpoint,{method:'POST'})
    .then(function(r){
      if(r.status===200){return;}
      else if(r.status===429){busy=false;setN(SKEY,0);setN(KEY,Date.now()+COOL);say('เพิ่งอัปเดตไปแล้ว รอสักครู่','Just updated; please wait a moment',true);startTimer();}
      else{fail('ส่งคำสั่งไม่สำเร็จ กรุณาลองใหม่อีกครั้ง','Could not send the request. Please try again.',true);}
    })
    .catch(function(){fail('ส่งคำสั่งไม่สำเร็จ กรุณาลองใหม่อีกครั้ง','Could not send the request. Please try again.',true);});
  });
  /* resume after manual reload / reopen */
  var st0=getN(SKEY);
  if(st0&&Date.now()-st0<MAXWAIT){busy=true;startTimer();startPolling();}
  else{setN(SKEY,0);tick();if(getN(KEY)>Date.now())startTimer();}
})();

